FIELDS={
 '초등영어':dict(label='초등 영어',focus='파닉스·어휘·읽기·듣기·쓰기',description='초등 영어 교재 20종의 파닉스·독해·어휘·듣기·쓰기 범위와 학생 상태, 권·단계 선택 조건을 비교합니다.',answer='알파벳 소리와 단어 읽기, 문장 이해, 듣기와 쓰기를 각각 확인하세요. 한 시리즈의 Level 숫자를 학교 학년으로 해석하기보다 실제 샘플의 읽기와 과제를 살펴봅니다.',checks=[('소리와 단어 읽기','짧은 단어를 읽을 때 소리 규칙에서 막히는지, 아는 단어를 문장에서도 읽을 수 있는지 봅니다.'),('문장과 이야기 이해','낱말 뜻을 아는 것과 문장의 질문에 답하는 것을 나누어 확인하세요.'),('듣기와 쓰기','읽기 단계가 같아도 음성 이해와 문장 작성은 다를 수 있습니다. 보강할 영역을 따로 고릅니다.')],guides=['영어학습관리','영어듣기복습법','영어서술형쓰기'],edition='영어 원서의 Level·Stage는 학교 학년과 같은 단위가 아닙니다. 현재 권의 지문·음성·쓰기 과제를 각각 확인하세요.'),
 '초등수학':dict(label='초등 수학',focus='개념·연산·유형·문장제·심화',description='초등 수학 교재 20종의 개념·연산·유형·문장제·심화 범위와 학생별 선정 기준, 학년·학기 조건을 비교합니다.',answer='개념을 설명하는지, 기본 계산을 혼자 하는지, 문장제의 관계를 식으로 옮기는지 나누어 보세요. 현재 단원의 부족한 부분에 맞춰 개념 교재와 보강 교재의 역할을 정합니다.',checks=[('개념 설명','그림과 수의 관계를 말로 설명한 뒤 기본 문제에 적용하는지 봅니다.'),('계산의 정확도','틀린 계산 줄과 이유를 남기세요. 개념 부족과 연산 오류는 보완할 자료가 다를 수 있습니다.'),('문장제와 풀이 설명','조건을 읽고 식을 만든 이유를 말할 수 있는지 확인합니다. 심화는 현재 수행을 보고 검토하세요.')],guides=['수학기초점검','계산실수줄이기','수학문장제읽기'],edition='학교 학년·학기와 단원 순서를 확인하세요. 연산 보강도 현재 단원에서 필요한 계산과 연결해 범위를 고릅니다.'),
 '중등영어':dict(label='중등 영어',focus='어휘·문법·구문·독해·듣기·서술형',description='중등 영어 교재 20종의 어휘·문법·구문·독해·듣기·서술형 영역과 주분류·추가 분류 및 단계 조건을 비교합니다.',answer='단어가 부족한지, 문장 구조에서 막히는지, 지문과 답의 근거를 연결하기 어려운지 먼저 구분하세요. 일반 교재와 학교 내신 자료를 나누어 필요한 영역만 보강합니다.',checks=[('어휘와 구문','뜻이 모르는 단어와 단어는 알지만 연결이 어려운 문장을 따로 표시합니다.'),('독해와 문법 적용','규칙을 외운 뒤 실제 문장과 지문에서도 근거를 설명할 수 있는지 보세요.'),('학교 자료와 쓰기','교과서·부교재·배부 자료의 현재 범위와 서술형 요구를 먼저 확인합니다.')],guides=['영어문장구조읽기','영어내신준비','영어서술형쓰기'],edition='내신 교재는 학교 교과서의 출판사·저자·학년·개정판과 평가 범위를 확인하세요. 일반 문법·독해 교재가 학교 자료를 대신하는 것은 아닙니다.'),
 '중등수학':dict(label='중등 수학',focus='선수 개념·계산·유형·서술형·심화',description='중등 수학 교재 20종의 개념·유형·기초 반복·내신 심화 영역과 학생 상태, 학년·학기·판본 조건을 비교합니다.',answer='현재 단원의 선수 개념, 기본 예제와 유형 적용을 구분해 확인하세요. 개념서와 유형서의 목적을 정하고, 복합 조건의 풀이를 설명할 수 있을 때 심화 후보를 살펴봅니다.',checks=[('선수 개념의 연결','이전 단원의 내용에서 막히는지 현재 문제의 첫 식을 보며 확인합니다.'),('기본과 유형 적용','해설을 본 기본 예제와 새 유형을 혼자 푼 결과를 구분하세요.'),('복합 조건과 서술형','어떤 조건을 사용해 식을 만들었는지 설명한 자료를 남깁니다.')],guides=['수학기초점검','수학서술형풀이','수학오답관리'],edition='같은 시리즈를 함께 볼 때도 학년·학기·개정 교육과정이 일치하는지 확인하세요. 중3은 현재 학교 적용 판본을 별도로 확인합니다.'),
 '고등수학':dict(label='고등 수학',focus='과목별 개념·내신 유형·심화·기출',description='고등 수학 교재 20종의 개념·내신 유형·심화·기출 역할과 학생별 선택 기준, 학교 과목·교육과정 조건을 비교합니다.',answer='먼저 학교 과목과 교육과정을 확인하고, 계산·핵심 개념·풀이 전략 중 부족한 부분을 찾으세요. 내신 유형과 기출 분석은 목표가 다를 수 있으므로 교재의 역할을 나눕니다.',checks=[('학교 과목과 선수 개념','공통수학·대수 등 실제 학교 과목에 맞는 권을 고르고 필요한 이전 개념을 확인합니다.'),('풀이 선택과 조건','문제의 첫 접근, 선택한 식과 조건을 설명할 수 있는지 봅니다.'),('내신과 기출 목표','현재 학교 범위 보완과 응시 학년도의 기출 준비를 같은 진도표로 가정하지 마세요.')],guides=['고등수학모의고사분석','수학서술형풀이','수학선행학습점검'],edition='학교 과목명·개정 교육과정과 응시 학년도를 함께 확인하세요. 발행 연도가 최신이라는 이유만으로 학생의 과목 체계와 일치한다고 단정하지 않습니다.'),
 '고등영어':dict(label='고등 영어',focus='어휘·구문·어법·독해·듣기·기출',description='고등 영어 교재 20종의 어휘·구문·어법·독해·듣기·기출 역할과 학생 상태, 단계·응시 학년도 조건을 비교합니다.',answer='문장 해석, 지문 이해와 선택지 판단을 나누어 보세요. 기본 어휘·구문이 필요한지, 유형·기출 적용을 연습할지 정하고 학교 내신과 응시 학년도의 자료를 따로 확인합니다.',checks=[('어휘와 문장 해석','단어 뜻만 더 외우면 되는지, 구문 연결의 설명이 필요한지 실제 문장으로 확인합니다.'),('독해와 선택지 근거','지문의 범위와 선택지의 표현을 대조한 기록을 남깁니다.'),('학교 범위와 실전 자료','교과서·부교재·학교 범위와 EBS·기출의 응시 학년도를 구분해 확인합니다.')],guides=['영어독해근거찾기','영어내신준비','영어듣기복습법'],edition='EBS·기출은 발행 연도와 응시 학년도를 구분하세요. 학교 내신은 교과서·부교재·배부 자료와 실제 평가 안내를 우선합니다.'),
}
# Each worked activity uses newly authored examples, not pages from a textbook.
ACTIVITIES={
 ('초등영어','기초반'):('소리와 단어 읽기부터','cat의 소리를 나누어 읽고 cap처럼 끝소리가 달라진 단어도 읽어 봅니다. 단어를 이미 외운 것과 소리 규칙으로 읽은 것을 나누어 적으세요.','읽기에서는 잘되지만 음성만 들으면 막히는 표현을 따로 남겨 듣기 보강의 범위를 고릅니다.','소리 규칙 → 새 단어 읽기 → 짧은 표현 듣기'),
 ('초등영어','표준반'):('읽은 문장을 질문과 연결하기','The dog is under the chair.를 읽고 “Where is the dog?”에 답해 봅니다. 단어 번역과 문장의 위치 관계를 이해한 결과를 구분하세요.','통합 교재의 읽기·말하기·듣기 중 현재 가능한 활동을 확인하고 부족한 어휘나 독해만 보강합니다.','문장 읽기 → 질문에 답하기 → 생활 표현 바꾸기'),
 ('초등영어','심화반'):('주제를 읽고 짧게 설명하기','식물에 관한 쉬운 글을 읽었다면 중심 내용과 이를 뒷받침하는 정보를 나누어 설명합니다. 설명할 때 원문의 뜻을 넘겨 추측하지 않습니다.','읽기 수준과 쓰기 수준이 다르면 지문과 쓰기 과제의 단계를 각각 고르세요. 문단 길이보다 연결된 내용과 이유를 확인합니다.','주제 읽기 → 정보 연결 → 문단 초안과 수정'),
 ('초등수학','기초반'):('그림과 계산을 같은 뜻으로 설명하기','12÷3을 같은 크기의 세 묶음으로 나누는 그림과 연결해 설명해 봅니다. 그림 설명과 계산 결과를 따로 확인하세요.','연산 교재는 부족한 계산을 보강하는 역할로 두고 현재 단원의 개념 설명과 기본 적용을 함께 봅니다.','그림 설명 → 기본 계산 → 같은 개념 적용'),
 ('초등수학','표준반'):('문장제의 관계를 식으로 옮기기','사과가 세 묶음이고 한 묶음에 네 개씩 있다면 무엇을 구하는지 표시하고 3×4를 쓴 이유를 설명합니다. 숫자만 고르는 것과 관계를 읽는 것을 구분하세요.','유형 문제의 풀이 근거를 남기고 조건 읽기가 어려운 부분을 별도 보강 대상으로 고릅니다.','조건 표시 → 유형 적용 → 풀이 근거 설명'),
 ('초등수학','심화반'):('바뀐 조건을 하나씩 확인하기','같은 넓이를 갖는 직사각형의 변 길이를 바꾸는 상황에서 가능한 경우를 정리하고 왜 같은 넓이인지 설명해 봅니다.','심화 후보 두 종을 함께 시작하기 전에 한 권의 현재 단계에서 혼자 가능한 풀이와 질문이 필요한 조건을 확인합니다.','기본 근거 → 조건 변화 → 여러 풀이 비교'),
 ('중등영어','기초반'):('문법 이름을 문장 해석과 연결하기','She studies English after school.에서 주어·동사와 시간을 나타내는 표현을 나누고 문장 전체의 뜻을 말해 봅니다.','문법 문제의 정답과 문장을 읽은 결과를 따로 기록하세요. 낮은 단계의 구문과 어휘 보강이 필요한지 실제 자료로 확인합니다.','기본 문법 → 문장 연결 → 짧은 독해'),
 ('중등영어','표준반'):('독해에서 정답 이유까지 적기','지문에 some students라고 쓰여 있는데 선택지에 all students라고 쓰였다면 달라진 범위를 표시하고 판단 이유를 설명해 봅니다.','독해를 중심으로 문법과 어휘의 부족한 항목을 고르되 각 시리즈의 과제가 같은 내용을 반복하는지 확인합니다.','지문 이해 → 선택지 대조 → 문법·어휘 보강'),
 ('중등영어','심화반'):('긴 글의 근거를 서술형으로 옮기기','글에서 비교하는 두 대상의 공통점과 차이를 각각 표시하고 질문이 요구한 항목만 문장으로 묶어 봅니다.','독해 난도와 글쓰기 과제를 따로 조정하세요. 학교 수행평가의 분량·형식·제출 조건은 실제 안내를 기준으로 확인합니다.','긴 지문 구조 → 근거 표시 → 서술형 수정'),
 ('중등수학','기초반'):('계산과 개념에서 막힌 줄 구분하기','2(x-3)=10에서 x-3=5까지 변형하고 양변에 3을 더하는 이유를 말해 봅니다. 계산 오류와 식을 바꾸는 이유의 어려움을 구분하세요.','빈 단원의 선수 개념을 보완한 뒤 현재 학년의 기본 예제에 다시 연결합니다. 반복 문제를 맞힌 것으로 전체 이해를 확정하지 않습니다.','선수 개념 → 기본 예제 → 도움 없이 재확인'),
 ('중등수학','표준반'):('개념서의 예제를 유형 문제에 적용하기','일차방정식을 풀 때 한 번 본 예제의 숫자가 바뀌어도 같은 변형의 이유를 설명하며 풀어 봅니다.','개념원리와 RPM 같은 연결 후보도 학년·학기·판본을 일치시키고 개념 설명과 유형 적용의 역할을 나누어 사용합니다.','개념 설명 → 새 유형 → 첫 오류와 재풀이'),
 ('중등수학','심화반'):('여러 조건을 사용한 순서 설명하기','두 도형의 넓이를 비교하는 문제에서 어떤 길이와 관계를 먼저 사용했는지 표시하고 식의 연결을 설명해 봅니다.','심화 교재는 순차 검토 후보로 보세요. 한 권에서 계속 막히는 경우에는 필요한 기본 개념과 조건 읽기를 먼저 보완합니다.','조건 구조 → 풀이 전략 → 다른 접근 검토'),
 ('고등수학','기초반'):('학교 과목의 핵심 예제부터 연결하기','이차식 x²+5x+6을 (x+2)(x+3)으로 인수분해한 뒤 다시 전개해 같은 식인지 확인합니다. 필요한 계산과 개념 설명을 구분해 보세요.','새 과목의 어려움이 이전 단원의 계산이나 개념에서 시작됐는지 보고 보강 범위를 정합니다. 학교 과목에 맞는 권을 먼저 확인하세요.','과목 확인 → 핵심 개념 → 기본 적용 보완'),
 ('고등수학','표준반'):('유형 선택의 이유를 남기기','방정식의 해를 구하는 문제에서 인수분해를 선택했다면 왜 이 식에 적용할 수 있는지 적고 구한 값을 원래 식에 대입해 봅니다.','유형 교재의 모든 난도를 같은 분량으로 배치하기보다 현재 수행에 맞는 구간과 질문할 문항을 정합니다.','개념과 조건 → 유형 선택 → 결과 검토'),
 ('고등수학','심화반'):('복합 조건의 연결을 설명하기','매개변수가 있는 식에서는 값의 범위를 먼저 정리하고, 각 경우에 어떤 조건이 유지되는지 풀이 옆에 적어 봅니다.','고난도 교재의 이름보다 현재 풀이에서 조건을 누락하지 않는지 확인하세요. 내신 심화와 수능 기출은 학교 과목·응시 학년도에 맞게 역할을 구분합니다.','경우와 조건 → 풀이 근거 → 새로운 조건 적용'),
 ('고등영어','기초반'):('단어의 뜻과 문장의 연결 나누기','The book that I borrowed was useful.에서 문장의 핵심과 book을 설명하는 부분을 나누고 뜻을 말해 봅니다.','읽기에서 막힌 단어와 구조를 따로 기록하고 입문 구문과 어휘의 분량을 현재 수행에 맞게 조정합니다.','어휘·구문 확인 → 짧은 독해 → 재해석'),
 ('고등영어','표준반'):('유형의 이름보다 근거 확인하기','반대 의견을 소개한 뒤 필자의 결론이 이어지는 글이라면 전환 표현과 마지막 주장을 표시하고 선택지와 대조해 봅니다.','어법 보강은 실제 지문의 문장을 사용해 규칙과 적용 이유를 설명하도록 연결합니다. 학교 범위와 수능 유형의 과제 목적을 구분하세요.','글의 구조 → 선택지 근거 → 어법 적용'),
 ('고등영어','심화반'):('추론 범위와 실제 근거 구분하기','긴 문장에서 조건을 나타내는 절을 표시하고 그 조건을 빼면 선택지의 주장이 달라지는지 비교해 봅니다.','기출과 EBS 자료는 응시 학년도와 해당 권을 먼저 확인하세요. 틀린 선택지의 이유와 해설 없이 다시 판단한 결과를 남깁니다.','복잡한 구문 → 추론 근거 → 기출 재확인'),
}
